  unfold Cc_1RB0RD_1LC1RA_0RB0LC_0LD1RC, cden, P0_1RB0RD_1LC1RA_0RB0LC_0LD1RC, P1_1RB0RD_1LC1RA_0RB0LC_0LD1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
