    rewrite (srun_sound tm false true chz_1RB0RD_1LC1RA_0RB0LC_0LD1RC Z0_1RB0RD_1LC1RA_0RB0LC_0LD1RC Z1_1RB0RD_1LC1RA_0RB0LC_0LD1RC 0 2
               run_z_1RB0RD_1LC1RA_0RB0LC_0LD1RC (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
