    exists (4 * j' + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0RD_1LC1RA_0RB0LC_0LD1RC P0_1RB0RD_1LC1RA_0RB0LC_0LD1RC P1_1RB0RD_1LC1RA_0RB0LC_0LD1RC 4 6
