(** ** The lap *)

Lemma lap_1RB0RD_1LC1RA_0RB0LC_0LD1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
