    apply (lap_of_run tm Cc true true cho_1RB0RD_1LC1RA_0RB0LC_0LD1RC B0_1RB0RD_1LC1RA_0RB0LC_0LD1RC B1_1RB0RD_1LC1RA_0RB0LC_0LD1RC 4 6 p j' [] []).
    + exact run_ovf_1RB0RD_1LC1RA_0RB0LC_0LD1RC.
    + reflexivity.
