  - exact bootq_1RB0RD_1LC1RA_0RB0LC_0LD1RC.
  - intros p _. apply lap_1RB0RD_1LC1RA_0RB0LC_0LD1RC.
  - intros t Ht p _. apply fire_1RB0RD_1LC1RA_0RB0LC_0LD1RC. exact Ht.
  - exact wit_1RB0RD_1LC1RA_0RB0LC_0LD1RC.
  - apply qcleb_QE_03. reflexivity.
Qed.

Theorem qhtr_1RB0RD_1LC1RA_0RB0LC_0LD1RC : NonHalt tm_1RB0RD_1LC1RA_0RB0LC_0LD1RC /\ QHBoundTr 32779478 tm_1RB0RD_1LC1RA_0RB0LC_0LD1RC /\ QuasiHaltsTr tm_1RB0RD_1LC1RA_0RB0LC_0LD1RC.
