(** 1RB0RD_1LC1RA_0RB0LC_1LB1LA *)
(** 1RB0RD_1LC1RA_0RB0LC_1LB1LA -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0RD_1LC1RA_0RB0LC_1LB1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S0 DL StC
