(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0RD_1LC1RA_0RB0LC_1LB1LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z0_1RB0RD_1LC1RA_0RB0LC_1LB1LA /\
  cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z1_1RB0RD_1LC1RA_0RB0LC_1LB1LA = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_00_10_1.cview_some_Alph_00_10_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0RD_1LC1RA_0RB0LC_1LB1LA, cden, Z0_1RB0RD_1LC1RA_0RB0LC_1LB1LA, Z1_1RB0RD_1LC1RA_0RB0LC_1LB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0RD_1LC1RA_0RB0LC_1LB1LA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j P0_1RB0RD_1LC1RA_0RB0LC_1LB1LA /\
  cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j P1_1RB0RD_1LC1RA_0RB0LC_1LB1LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_00_10_1.cview_some_Alph_00_10_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB0RD_1LC1RA_0RB0LC_1LB1LA, cden, P0_1RB0RD_1LC1RA_0RB0LC_1LB1LA, P1_1RB0RD_1LC1RA_0RB0LC_1LB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0RD_1LC1RA_0RB0LC_1LB1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0RD_1LC1RA_0RB0LC_1LB1LA p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0RD_1LC1RA_0RB0LC_1LB1LA Z0_1RB0RD_1LC1RA_0RB0LC_1LB1LA Z1_1RB0RD_1LC1RA_0RB0LC_1LB1LA 0 2
               run_z_1RB0RD_1LC1RA_0RB0LC_1LB1LA (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0RD_1LC1RA_0RB0LC_1LB1LA p j' q0 E) as (HA & HB).
    exists (4 * j' + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0RD_1LC1RA_0RB0LC_1LB1LA P0_1RB0RD_1LC1RA_0RB0LC_1LB1LA P1_1RB0RD_1LC1RA_0RB0LC_1LB1LA 4 6
               run_p_1RB0RD_1LC1RA_0RB0LC_1LB1LA (Ap_Alph_00_10_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB0RD_1LC1RA_0RB0LC_1LB1LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0RD_1LC1RA_0RB0LC_1LB1LA.
Proof.
  intros p j E. destruct (Alph_00_10_1.cview_none_Alph_00_10_1 p j E) as (H1 & _).
  unfold Cc_1RB0RD_1LC1RA_0RB0LC_1LB1LA, cden, B0_1RB0RD_1LC1RA_0RB0LC_1LB1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0RD_1LC1RA_0RB0LC_1LB1LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0RD_1LC1RA_0RB0LC_1LB1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RD_1LC1RA_0RB0LC_1LB1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_00_10_1.cview_none_Alph_00_10_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RD_1LC1RA_0RB0LC_1LB1LA
             = (StC, (rep [S0;S0] (S j) ++ [S1], S0, []))).
  { unfold cden, B1_1RB0RD_1LC1RA_0RB0LC_1LB1LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S0] (S j) ++ [S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB0RD_1LC1RA_0RB0LC_1LB1LA. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0RD_1LC1RA_0RB0LC_1LB1LA. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0RD_1LC1RA_0RB0LC_1LB1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RD_1LC1RA_0RB0LC_1LB1LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RD_1LC1RA_0RB0LC_1LB1LA B0_1RB0RD_1LC1RA_0RB0LC_1LB1LA B1_1RB0RD_1LC1RA_0RB0LC_1LB1LA 4 6 p j' [] []).
    + exact run_ovf_1RB0RD_1LC1RA_0RB0LC_1LB1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RD_1LC1RA_0RB0LC_1LB1LA p j' E).
    + exact (geo_1RB0RD_1LC1RA_0RB0LC_1LB1LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0RD_1LC1RA_0RB0LC_1LB1LA : stepn tmm_1RB0RD_1LC1RA_0RB0LC_1LB1LA 25 InitES = Some (lift (Cc 4)).
Proof.
  assert (H : match csteps tmm_1RB0RD_1LC1RA_0RB0LC_1LB1LA 25 c0 with
              | Some c => ceqb c (Cc 4) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0RD_1LC1RA_0RB0LC_1LB1LA 25 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0RD_1LC1RA_0RB0LC_1LB1LA : existsb (fun tg => cfires tmm_1RB0RD_1LC1RA_0RB0LC_1LB1LA c0 25 tg) pins_1RB0RD_1LC1RA_0RB0LC_1LB1LA = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RD_1LC1RA_0RB0LC_1LB1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RD_1LC1RA_0RB0LC_1LB1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RD_1LC1RA_0RB0LC_1LB1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RD_1LC1RA_0RB0LC_1LB1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RD_1LC1RA_0RB0LC_1LB1LA : forall t, ~ In t pins_1RB0RD_1LC1RA_0RB0LC_1LB1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RD_1LC1RA_0RB0LC_1LB1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0RD_1LC1RA_0RB0LC_1LB1LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RD_1LC1RA_0RB0LC_1LB1LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RD_1LC1RA_0RB0LC_1LB1LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RD_1LC1RA_0RB0LC_1LB1LA
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RD_1LC1RA_0RB0LC_1LB1LA
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtrm_1RB0RD_1LC1RA_0RB0LC_1LB1LA : NonHalt tmm_1RB0RD_1LC1RA_0RB0LC_1LB1LA /\ QHBoundTr 32779478 tmm_1RB0RD_1LC1RA_0RB0LC_1LB1LA /\ QuasiHaltsTr tmm_1RB0RD_1LC1RA_0RB0LC_1LB1LA.
Proof.
  apply (lap_qh_stage tmm_1RB0RD_1LC1RA_0RB0LC_1LB1LA pins_1RB0RD_1LC1RA_0RB0LC_1LB1LA Cc 4 25 32779478).
  - exact bootq_1RB0RD_1LC1RA_0RB0LC_1LB1LA.
  - intros p _. apply lap_1RB0RD_1LC1RA_0RB0LC_1LB1LA.
  - intros t Ht p _. apply fire_1RB0RD_1LC1RA_0RB0LC_1LB1LA. exact Ht.
  - exact wit_1RB0RD_1LC1RA_0RB0LC_1LB1LA.
  - apply qcleb_QE_03. reflexivity.
Qed.

Theorem qhtr_1RB0RD_1LC1RA_0RB0LC_1LB1LA : NonHalt tm_1RB0RD_1LC1RA_0RB0LC_1LB1LA /\ QHBoundTr 32779478 tm_1RB0RD_1LC1RA_0RB0LC_1LB1LA /\ QuasiHaltsTr tm_1RB0RD_1LC1RA_0RB0LC_1LB1LA.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB0RD_1LC1RA_0RB0LC_1LB1LA). rewrite mirror_ok_1RB0RD_1LC1RA_0RB0LC_1LB1LA. exact qhtrm_1RB0RD_1LC1RA_0RB0LC_1LB1LA. Qed.

