Lemma lapi_1RB0RD_1LC1RA_0RB0LC_1LD1LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0RD_1LC1RA_0RB0LC_1LD1LC p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0RD_1LC1RA_0RB0LC_1LD1LC Z0_1RB0RD_1LC1RA_0RB0LC_1LD1LC Z1_1RB0RD_1LC1RA_0RB0LC_1LD1LC 0 2
               run_z_1RB0RD_1LC1RA_0RB0LC_1LD1LC (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0RD_1LC1RA_0RB0LC_1LD1LC p j' q0 E) as (HA & HB).
    exists (4 * j' + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0RD_1LC1RA_0RB0LC_1LD1LC P0_1RB0RD_1LC1RA_0RB0LC_1LD1LC P1_1RB0RD_1LC1RA_0RB0LC_1LD1LC 4 6
               run_p_1RB0RD_1LC1RA_0RB0LC_1LD1LC (Ap_Alph_00_10_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB0RD_1LC1RA_0RB0LC_1LD1LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0RD_1LC1RA_0RB0LC_1LD1LC.
