  unfold Cc_1RB0RD_1LC1RA_0RB0LC_1LD1LC, cden, B0_1RB0RD_1LC1RA_0RB0LC_1LD1LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0RD_1LC1RA_0RB0LC_1LD1LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0RD_1LC1RA_0RB0LC_1LD1LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RD_1LC1RA_0RB0LC_1LD1LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_00_10_1.cview_none_Alph_00_10_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RD_1LC1RA_0RB0LC_1LD1LC
             = (StC, (rep [S0;S0] (S j) ++ [S1], S0, [S1]))).
  { unfold cden, B1_1RB0RD_1LC1RA_0RB0LC_1LD1LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S0] (S j) ++ [S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_1RB0RD_1LC1RA_0RB0LC_1LD1LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0RD_1LC1RA_0RB0LC_1LD1LC. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0RD_1LC1RA_0RB0LC_1LD1LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RD_1LC1RA_0RB0LC_1LD1LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RD_1LC1RA_0RB0LC_1LD1LC B0_1RB0RD_1LC1RA_0RB0LC_1LD1LC B1_1RB0RD_1LC1RA_0RB0LC_1LD1LC 4 6 p j' [] []).
    + exact run_ovf_1RB0RD_1LC1RA_0RB0LC_1LD1LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RD_1LC1RA_0RB0LC_1LD1LC p j' E).
    + exact (geo_1RB0RD_1LC1RA_0RB0LC_1LD1LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0RD_1LC1RA_0RB0LC_1LD1LC : stepn tmm_1RB0RD_1LC1RA_0RB0LC_1LD1LC 15 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0RD_1LC1RA_0RB0LC_1LD1LC 15 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0RD_1LC1RA_0RB0LC_1LD1LC 15 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0RD_1LC1RA_0RB0LC_1LD1LC : existsb (fun tg => cfires tmm_1RB0RD_1LC1RA_0RB0LC_1LD1LC c0 15 tg) pins_1RB0RD_1LC1RA_0RB0LC_1LD1LC = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RD_1LC1RA_0RB0LC_1LD1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RD_1LC1RA_0RB0LC_1LD1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RD_1LC1RA_0RB0LC_1LD1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RD_1LC1RA_0RB0LC_1LD1LC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RD_1LC1RA_0RB0LC_1LD1LC : forall t, ~ In t pins_1RB0RD_1LC1RA_0RB0LC_1LD1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RD_1LC1RA_0RB0LC_1LD1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0RD_1LC1RA_0RB0LC_1LD1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RD_1LC1RA_0RB0LC_1LD1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RD_1LC1RA_0RB0LC_1LD1LC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RD_1LC1RA_0RB0LC_1LD1LC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RD_1LC1RA_0RB0LC_1LD1LC
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
Qed.

Theorem qhtrm_1RB0RD_1LC1RA_0RB0LC_1LD1LC : NonHalt tmm_1RB0RD_1LC1RA_0RB0LC_1LD1LC /\ QHBoundTr 32779478 tmm_1RB0RD_1LC1RA_0RB0LC_1LD1LC /\ QuasiHaltsTr tmm_1RB0RD_1LC1RA_0RB0LC_1LD1LC.
Proof.
  apply (lap_qh_stage tmm_1RB0RD_1LC1RA_0RB0LC_1LD1LC pins_1RB0RD_1LC1RA_0RB0LC_1LD1LC Cc 1 15 32779478).
  - exact bootq_1RB0RD_1LC1RA_0RB0LC_1LD1LC.
  - intros p _. apply lap_1RB0RD_1LC1RA_0RB0LC_1LD1LC.
  - intros t Ht p _. apply fire_1RB0RD_1LC1RA_0RB0LC_1LD1LC. exact Ht.
  - exact wit_1RB0RD_1LC1RA_0RB0LC_1LD1LC.
  - apply qcleb_QE_03. reflexivity.
Qed.

Theorem qhtr_1RB0RD_1LC1RA_0RB0LC_1LD1LC : NonHalt tm_1RB0RD_1LC1RA_0RB0LC_1LD1LC /\ QHBoundTr 32779478 tm_1RB0RD_1LC1RA_0RB0LC_1LD1LC /\ QuasiHaltsTr tm_1RB0RD_1LC1RA_0RB0LC_1LD1LC.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB0RD_1LC1RA_0RB0LC_1LD1LC). rewrite mirror_ok_1RB0RD_1LC1RA_0RB0LC_1LD1LC. exact qhtrm_1RB0RD_1LC1RA_0RB0LC_1LD1LC. Qed.

End B_QE_03_015.

