    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RD_1RC1LD_0LD0RC_1LB0LA
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RD_1RC1LD_0LD0RC_1LB0LA
      with (l := [SWin 2; SCycL 2 0; SWin 1; SWinL 2]).
