(** The boot lands on the OFFSET inner anchor up to 0/0 trailing
    blanks. *)
Lemma gbo_1RB1LA_1LC1RD_1LA0LB_0LA0RB : forall j, lift (cden [] [] j BB1_1RB1LA_1LC1RD_1LA0LB_0LA0RB) = lift (Cin (xO (xI (pow2 j)))).
Proof.
