      exact firez_D1_1RB1LA_1LC1RD_1LA0LB_0LA0RB.
    + exact (fireo_1RB1LA_1LC1RD_1LA0LB_0LA0RB [SRotL 1; SWin 1; SCycL 2 0; SWin 6] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1' E1).
Qed.

