Lemma gbo_1RB1LA_1LC1RD_1LA0LC_0LA0RB : forall j, lift (cden [] [] j BB1_1RB1LA_1LC1RD_1LA0LC_0LA0RB) = lift (Cin (xO (xI (pow2 j)))).
