    + exact (fireo_1RB1LA_1LC1RD_1LA0LC_0LA0RB [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 1] (StB, S0) ltac:(vm_compute; reflexivity)
