(** ** The lap *)

Lemma lap_1RB1LA_1LC1RD_1LA1LA_0LA0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_1LC1RD_1LA1LA_0LA0RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LA_1LC1RD_1LA1LA_0LA0RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1LA_1LC1RD_1LA1LA_0LA0RB : stepn tm_1RB1LA_1LC1RD_1LA1LA_0LA0RB 22 InitES = Some (lift (Cc 2)).
