    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1LA_1RC0RB_1LC1LD____0LA Z0_1RB1LA_1RC0RB_1LC1LD____0LA Z1_1RB1LA_1RC0RB_1LC1LD____0LA 0 4
               run_z_1RB1LA_1RC0RB_1LC1LD____0LA (Kp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1LA_1RC0RB_1LC1LD____0LA p j' q0 E) as (HA & HB).
    exists (2 * j' + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LA_1RC0RB_1LC1LD____0LA P0_1RB1LA_1RC0RB_1LC1LD____0LA P1_1RB1LA_1RC0RB_1LC1LD____0LA 2 6
               run_p_1RB1LA_1RC0RB_1LC1LD____0LA (Kp q0 ++ [S0]) [] j'
