    + exact run_ovf_1RB1LA_1RC0RB_1LC1LD____0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_1RC0RB_1LC1LD____0LA p j' E).
    + exact (geo_1RB1LA_1RC0RB_1LC1LD____0LA p j' E).
