Qed.

Theorem qhtr_1RB1LA_1RC0RB_1LC1LD____0LA : NonHalt tm_1RB1LA_1RC0RB_1LC1LD____0LA /\ QHBoundTr 32779478 tm_1RB1LA_1RC0RB_1LC1LD____0LA /\ QuasiHaltsTr tm_1RB1LA_1RC0RB_1LC1LD____0LA.
