(** board for 1RB1LA_1LC1RD_1LA1RA_0LA0RB (emit_lapcert.py --qh) *)
Module B_QE_03_034.
Import BBB4.BBB4_Statement BBB4.CTape BBB4.Counters.WTape BBB4.Counters.LapGlue BBB4.Counters.LapGlueQH BBB4.Counters.LapGlueAbs BBB4.Counters.MonoCounter BBB4.Counters.JpCounter BBB4.Counters.Alph_10_11_11 BBB4.Counters.LapCertGlue BBB4.Counters.LapCertGlueLift BBB4.Counters.IXPGadgets BBB4.Counters.NestedLap BBB4.Counters.NestedLapLift BBB4.Counters.ILCounter BBB4.Census.TNF_QH BBB4.Checkers.LapDecider BBB4.BBBT4_Statement BBB4.Checkers.WrapTr BBB4.Checkers.IRules.AnchorVisitsTr BBB4.Counters.LapGlueTr BBB4.ClosureTr BBB4.Counters.LapGlueQHTr BBB4.CensusTr.TNF_QHTr BBB4.CensusTr.QHConveyorTr.
Import ListNotations.

Definition mk_1RB1LA_1LC1RD_1LA1RA_0LA0RB (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1LA_1LC1RD_1LA1RA_0LA0RB.

(** 1RB1LA_1LC1RD_1LA1RA_0LA0RB *)
Definition tm_1RB1LA_1LC1RD_1LA1RA_0LA0RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S0 DR StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LA_1LC1RD_1LA1RA_0LA0RB : list Instr := [(StC, S1)].
Definition tmw_1RB1LA_1LC1RD_1LA1RA_0LA0RB : TM := tm_wrap_trs tm_1RB1LA_1LC1RD_1LA1RA_0LA0RB pins_1RB1LA_1LC1RD_1LA1RA_0LA0RB.
Local Notation tm := tmw_1RB1LA_1LC1RD_1LA1RA_0LA0RB.

Definition Cc_1RB1LA_1LC1RD_1LA1RA_0LA0RB (p : positive) : cconf := (StD, (Ap_Alph_10_11_11 p ++ [S1;S1;S0], S0, [])).
Local Notation Cc := Cc_1RB1LA_1LC1RD_1LA1RA_0LA0RB.

(** ** The certificate *)

Definition A0_1RB1LA_1LC1RD_1LA1RA_0LA0RB : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB1LA_1LC1RD_1LA1RA_0LA0RB : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chi_1RB1LA_1LC1RD_1LA1RA_0LA0RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_int_1RB1LA_1LC1RD_1LA1RA_0LA0RB : srun tm false true chi_1RB1LA_1LC1RD_1LA1RA_0LA0RB A0_1RB1LA_1LC1RD_1LA1RA_0LA0RB = Some (A1_1RB1LA_1LC1RD_1LA1RA_0LA0RB, 4, 4).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1LA_1LC1RD_1LA1RA_0LA0RB : sconf := mkC StD (mkS [] [S1;S1] 1 1 [S1;S1;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1LA_1LC1RD_1LA1RA_0LA0RB : sconf := mkC StD (mkS [] [S1;S0] 1 2 [S1;S1;S1;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StD *)
Definition Cin_1RB1LA_1LC1RD_1LA1RA_0LA0RB (v : positive) : cconf := (StD, (Ip v ++ [S0;S1;S1], S0, [])).
Local Notation Cin := Cin_1RB1LA_1LC1RD_1LA1RA_0LA0RB.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1LA_1LC1RD_1LA1RA_0LA0RB : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1LA_1LC1RD_1LA1RA_0LA0RB : sconf := mkC StD (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_1RB1LA_1LC1RD_1LA1RA_0LA0RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_inner_1RB1LA_1LC1RD_1LA1RA_0LA0RB : srun tm false true chn_1RB1LA_1LC1RD_1LA1RA_0LA0RB AI0_1RB1LA_1LC1RD_1LA1RA_0LA0RB = Some (AI1_1RB1LA_1LC1RD_1LA1RA_0LA0RB, 4, 4).
Proof. vm_compute. reflexivity. Qed.

(** The OFFSET start: [E (2^(n+2)+2)] is fixed digit blocks, then the rep.
    Its block count is one short of the outer index, which is why [lapo_]
    below REINDEXES at [j = S j']. *)
Lemma epre_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall n, Ip (xO (xI (pow2 n))) = [S1;S0;S1;S1] ++ rep [S1;S0] n ++ [S1].
Proof.
  intro n. cbn [Ip]. rewrite epow2_1RB1LA_1LC1RD_1LA1RA_0LA0RB.
  cbn [app]. rewrite <- ?app_assoc. cbn [app]. reflexivity.
Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LA_1LC1RD_1LA1RA_0LA0RB : sconf := mkC StD (mkS [S1;S0;S1;S1] [S1;S0] 1 1 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB1LA_1LC1RD_1LA1RA_0LA0RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 8; SCycR 2; SWin 2; SRotL 1; SWin 1; SRotL 1; SWin 4; SWinR 1].

Lemma run_boot_1RB1LA_1LC1RD_1LA1RA_0LA0RB : srun tm true true chb_1RB1LA_1LC1RD_1LA1RA_0LA0RB B0_1RB1LA_1LC1RD_1LA1RA_0LA0RB = Some (BB1_1RB1LA_1LC1RD_1LA1RA_0LA0RB, 4, 21).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LA_1LC1RD_1LA1RA_0LA0RB : sconf := mkC StD (mkS [] [S1;S1] 1 2 [S1;S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1LA_1LC1RD_1LA1RA_0LA0RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_exit_1RB1LA_1LC1RD_1LA1RA_0LA0RB : srun tm true true che_1RB1LA_1LC1RD_1LA1RA_0LA0RB BE0_1RB1LA_1LC1RD_1LA1RA_0LA0RB = Some (B1_1RB1LA_1LC1RD_1LA1RA_0LA0RB, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j A0_1RB1LA_1LC1RD_1LA1RA_0LA0RB.
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (H1 & _).
  unfold Cc_1RB1LA_1LC1RD_1LA1RA_0LA0RB, cden, A0_1RB1LA_1LC1RD_1LA1RA_0LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j A1_1RB1LA_1LC1RD_1LA1RA_0LA0RB = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (_ & H2).
  unfold Cc_1RB1LA_1LC1RD_1LA1RA_0LA0RB, cden, A1_1RB1LA_1LC1RD_1LA1RA_0LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (4 * j + 4). split; [lia|].
  rewrite (gsi_1RB1LA_1LC1RD_1LA1RA_0LA0RB p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1LA_1LC1RD_1LA1RA_0LA0RB A0_1RB1LA_1LC1RD_1LA1RA_0LA0RB A1_1RB1LA_1LC1RD_1LA1RA_0LA0RB 4 4
             run_int_1RB1LA_1LC1RD_1LA1RA_0LA0RB (Ap_Alph_10_11_11 q0 ++ [S1;S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1LA_1LC1RD_1LA1RA_0LA0RB p j q0 E).
Qed.

Lemma gso_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall p j, cview p = (S (S j), None) ->
  Cc p = cden [] [] j B0_1RB1LA_1LC1RD_1LA1RA_0LA0RB.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p (S j) E) as (H1 & _).
  unfold Cc_1RB1LA_1LC1RD_1LA1RA_0LA0RB, cden, B0_1RB1LA_1LC1RD_1LA1RA_0LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 1) with ((S j)) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall p j, cview p = (S (S j), None) ->
  lift (cden [] [] j B1_1RB1LA_1LC1RD_1LA1RA_0LA0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p (S j) E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_1LC1RD_1LA1RA_0LA0RB
             = (StD, (rep [S1;S0] (S (S j)) ++ [S1;S1;S1;S1], S0, []))).
  { unfold cden, B1_1RB1LA_1LC1RD_1LA1RA_0LA0RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 2) with (S (S j)) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S1;S0] (S (S j)) ++ [S1;S1;S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LA_1LC1RD_1LA1RA_0LA0RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LA_1LC1RD_1LA1RA_0LA0RB. reflexivity.
Qed.

Lemma gsn_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S0;S1;S1]) [] i AI0_1RB1LA_1LC1RD_1LA1RA_0LA0RB.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_1RB1LA_1LC1RD_1LA1RA_0LA0RB, cden, AI0_1RB1LA_1LC1RD_1LA1RA_0LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S0;S1;S1]) [] i AI1_1RB1LA_1LC1RD_1LA1RA_0LA0RB) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_1RB1LA_1LC1RD_1LA1RA_0LA0RB, cden, AI1_1RB1LA_1LC1RD_1LA1RA_0LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 4), (cden (Ip q0 ++ [S0;S1;S1]) [] i AI1_1RB1LA_1LC1RD_1LA1RA_0LA0RB).
  split; [lia|]. split; [| exact (gen_1RB1LA_1LC1RD_1LA1RA_0LA0RB v i q0 E)].
  rewrite (gsn_1RB1LA_1LC1RD_1LA1RA_0LA0RB v i q0 E).
  exact (srun_sound tm false true chn_1RB1LA_1LC1RD_1LA1RA_0LA0RB AI0_1RB1LA_1LC1RD_1LA1RA_0LA0RB AI1_1RB1LA_1LC1RD_1LA1RA_0LA0RB 4 4
           run_inner_1RB1LA_1LC1RD_1LA1RA_0LA0RB (Ip q0 ++ [S0;S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The boot lands on the OFFSET inner anchor up to 0/0 trailing
    blanks. *)
Lemma gbo_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall j, lift (cden [] [] j BB1_1RB1LA_1LC1RD_1LA1RA_0LA0RB) = lift (Cin (xO (xI (pow2 j)))).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LA_1LC1RD_1LA1RA_0LA0RB = (StD, ([S1;S0;S1;S1] ++ rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold cden, BB1_1RB1LA_1LC1RD_1LA1RA_0LA0RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (j + 1) by lia.
    rewrite rep_add. cbn [rep app]. rewrite ?app_nil_r.
    rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (xO (xI (pow2 j))) = (StD, ([S1;S0;S1;S1] ++ rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold Cin_1RB1LA_1LC1RD_1LA1RA_0LA0RB. rewrite epre_1RB1LA_1LC1RD_1LA1RA_0LA0RB.
    first [ rewrite <- ?app_assoc; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  (* The offset boot can land one written blank past the anchor on EITHER
     side, and [lift] sees neither.  Strip it FIRST: [cbn [app]] flattens
     `w ++ [S0]` into one literal and destroys the shape
     [WTape.lift_app_blank_l] matches on. *)
  rewrite HD, HC. rewrite ?lift_app_blank_l.
  cbn [app]. rewrite <- ?app_assoc. cbn [app].
  rewrite ?lbl_1RB1LA_1LC1RD_1LA1RA_0LA0RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** The offset family's all-ones fill is the ordinary one two octaves up:
    [fill (xO (xI (pow2 j))) = fill (pow2 (S (S j)))] by computation, so
    [cview_fill_pow2] still names the exit chain's start word. *)
Lemma gxi_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall j, Cin (fill (xO (xI (pow2 j)))) = cden [] [] j BE0_1RB1LA_1LC1RD_1LA1RA_0LA0RB.
Proof.
  intro j.
  assert (Hf : fill (xO (xI (pow2 j))) = fill (pow2 (S (S j))))
    by (cbn [pow2 fill]; reflexivity).
  rewrite Hf.
  destruct (ILCounter.cview_none_I (fill (pow2 (S (S j)))) (S (S j))
              (cview_fill_pow2 (S (S j)))) as (H1 & _).
  unfold Cin_1RB1LA_1LC1RD_1LA1RA_0LA0RB, cden, BE0_1RB1LA_1LC1RD_1LA1RA_0LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 2) with (S (S j)) by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1LA_1LC1RD_1LA1RA_0LA0RB p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** [cview p = (1, None)] forces [p = 1], where the offset family's count is
    empty: the overflow lap at p = 1 is ONE CONCRETE run, checked the way the
    bootstrap lemma is. *)
Lemma lapo0_1RB1LA_1LC1RD_1LA1RA_0LA0RB : exists n c', csteps tm n (Cc 1) = Some c'
    /\ lift c' = lift (Cc 2) /\ 0 < n.
Proof.
  exists 17.
  assert (H : match csteps tm 17 (Cc 1) with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 17 (Cc 1)) as [c|] eqn:E0; [|discriminate].
  exists c. split; [reflexivity|]. split; [apply ceqb_lift; exact H | lia].
Qed.

(** The outer OVERFLOW branch.  The offset family's block count is one short
    of the outer index, so the branch REINDEXES: the generic route runs at
    [j = S j'] and [j = 0] is the concrete lap above. *)
Lemma lapo_1RB1LA_1LC1RD_1LA1RA_0LA0RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  destruct j as [|j'].
  - rewrite (cview_none_shape p 0 E). exact lapo0_1RB1LA_1LC1RD_1LA1RA_0LA0RB.
  - apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_1LC1RD_1LA1RA_0LA0RB p (xO (xI (pow2 j')))).
    + exists (4 * j' + 21), (cden [] [] j' BB1_1RB1LA_1LC1RD_1LA1RA_0LA0RB).
      split; [lia|]. split; [| exact (gbo_1RB1LA_1LC1RD_1LA1RA_0LA0RB j')].
      rewrite (gso_1RB1LA_1LC1RD_1LA1RA_0LA0RB p j' E).
      exact (srun_sound tm true true chb_1RB1LA_1LC1RD_1LA1RA_0LA0RB B0_1RB1LA_1LC1RD_1LA1RA_0LA0RB BB1_1RB1LA_1LC1RD_1LA1RA_0LA0RB 4 21
               run_boot_1RB1LA_1LC1RD_1LA1RA_0LA0RB [] [] j' ltac:(reflexivity) ltac:(reflexivity)).
    + exists (4 * j' + 12), (cden [] [] j' B1_1RB1LA_1LC1RD_1LA1RA_0LA0RB).
      split; [| exact (geo_1RB1LA_1LC1RD_1LA1RA_0LA0RB p j' E)].
      rewrite (gxi_1RB1LA_1LC1RD_1LA1RA_0LA0RB j').
      exact (srun_sound tm true true che_1RB1LA_1LC1RD_1LA1RA_0LA0RB BE0_1RB1LA_1LC1RD_1LA1RA_0LA0RB B1_1RB1LA_1LC1RD_1LA1RA_0LA0RB 4 12
               run_exit_1RB1LA_1LC1RD_1LA1RA_0LA0RB [] [] j' ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** State StA's visit witness at the reindex's p = 1 case -- concrete. *)
Lemma visz_StA_1RB1LA_1LC1RD_1LA1RA_0LA0RB : exists k c, csteps tm k (Cc 1) = Some c /\ fst c = StA.
Proof. exists 1. eexists. split; [vm_compute; reflexivity | reflexivity]. Qed.

(** State StB's visit witness at the reindex's p = 1 case -- concrete. *)
