Lemma fire_1RB1LA_1LC1RD_1LA1RB_0LA0RB : forall t, ~ In t pins_1RB1LA_1LC1RD_1LA1RB_0LA0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
